contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _val, uint _val2) public payable {
        require(true);

        bool firstReverted;
        c.SetMinSum(_val); bool __rev0 = __ESBMC_reverted(); if (__rev0) { firstReverted = true; } else { firstReverted = false; }

        uint minSumAfterFirst = c.MinSum(); if (__ESBMC_reverted()) return;

        bool initializedReverted;
        c.Initialized(); bool __rev1 = __ESBMC_reverted(); if (__rev1) { initializedReverted = true; } else { initializedReverted = false; }

        bool secondReverted;
        c.SetMinSum(_val2); bool __rev2 = __ESBMC_reverted(); if (__rev2) { secondReverted = true; } else { secondReverted = false; }

        assert(
            (firstReverted && minSumAfterFirst == 0) ||
            (!firstReverted && minSumAfterFirst == _val && !initializedReverted && secondReverted)
        );
    }

    receive() external payable {}
}

