        c = new MONEY_BOX();
    }

    function _run(uint256 _val, uint256 _val2) internal {
        vm.assume(true);
        bool firstReverted;
        try c.SetMinSum(_val) { firstReverted = false; } catch { firstReverted = true; }
        uint256 minSumAfterFirst;
        try c.MinSum() returns (uint256 __r) { minSumAfterFirst = __r; } catch { return; }
        bool initializedReverted;
        try c.Initialized() { initializedReverted = false; } catch { initializedReverted = true; }
        bool secondReverted;
        try c.SetMinSum(_val2) { secondReverted = false; } catch { secondReverted = true; }
        assertTrue((firstReverted && minSumAfterFirst == 0) ||
            (!firstReverted && minSumAfterFirst == _val && !initializedReverted && secondReverted));
    }

    function testFuzz_run(uint256 _val, uint256 _val2) public {
        _run(_val, _val2);
    }

    receive() external payable {}
}
